<?php
declare(strict_types=1);
require_once __DIR__ . '/config/product_step11.php';
$error=null;$product=null;$history=[];$tiers=[];$id=isset($_GET['id'])&&is_numeric($_GET['id'])?(int)$_GET['id']:0;
try{$pdo=business_db();product_step11_ensure($pdo);$ctx=product_org_context($pdo);$orgId=(int)$ctx['organization_id'];if($id<=0)throw new RuntimeException('Choose a product from the catalog.');$stmt=$pdo->prepare("SELECT p.*,c.category_name,l.id listing_id,l.market_sku,pm.market_name,pm.currency_code,pi.image_url,pi.source_page_url,pi.source_name,pi.verification_status FROM products p LEFT JOIN product_categories c ON c.id=p.category_id JOIN product_market_listings l ON l.product_id=p.id AND l.organization_id=p.organization_id JOIN product_markets pm ON pm.id=l.market_id LEFT JOIN product_images pi ON pi.id=(SELECT pi2.id FROM product_images pi2 WHERE pi2.product_id=p.id ORDER BY pi2.is_primary DESC,pi2.sort_order,pi2.id LIMIT 1) WHERE p.organization_id=? AND p.id=? LIMIT 1");$stmt->execute([$orgId,$id]);$product=$stmt->fetch();if(!$product)throw new RuntimeException('Product was not found.');$stmt=$pdo->prepare("SELECT pv.id,pv.effective_from,pv.effective_to,pv.mrp,pv.volume_points,pv.status FROM product_price_versions pv WHERE pv.organization_id=? AND pv.listing_id=? ORDER BY pv.effective_from DESC,pv.id DESC");$stmt->execute([$orgId,(int)$product['listing_id']]);$history=$stmt->fetchAll();$tp=$pdo->prepare("SELECT t.tier_code,t.tier_name,t.customer_type,tp.price_amount FROM product_tier_prices tp JOIN product_discount_tiers t ON t.id=tp.discount_tier_id WHERE tp.price_version_id=? AND t.status='active' ORDER BY t.sort_order,t.id");if($history){$tp->execute([(int)$history[0]['id']]);$tiers=$tp->fetchAll();}}catch(Throwable $e){$error=$e->getMessage();}
$image=$product&&$product['image_url']?$product['image_url']:($product?'product_placeholder.php?'.http_build_query(['name'=>$product['product_name'],'stock'=>$product['sku'],'cat'=>$product['category_name']]):'');
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Product Detail - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="product_catalog.php"><img src="../img/logo.png" alt="logo"><span><strong>Healthcare Wellness Club</strong><small>Product & Price Pro • Product Detail</small></span></a><div class="os-top-actions"><a class="os-btn" href="product_compare.php?ids=<?= $id ?>">Compare</a><a class="os-btn" href="product_order_builder.php?add=<?= $id ?>">Add to Order</a><a class="os-btn primary" href="product_catalog.php">Catalog</a></div></div></header><div class="os-layout"><aside class="os-sidebar"><div class="os-nav-label">Product System</div><nav class="os-nav"><a href="product_catalog.php"><i class="dot"></i>Catalog</a><a class="active" href="#"><i class="dot"></i>Product Detail</a><a href="product_order_builder.php"><i class="dot"></i>Order Builder</a><a href="product_images.php"><i class="dot"></i>Image Manager</a><a href="product_price_history.php"><i class="dot"></i>Price History</a></nav></aside><main class="os-main"><?php if($error):?><div class="pp-alert bad"><strong>Product diagnostic:</strong> <?= product_h($error) ?></div><?php else:?><section class="pp-detail"><article class="os-card pp-detail-image"><img src="<?= product_h($image) ?>" alt="<?= product_h($product['product_name']) ?>" onerror="this.src='<?= product_h('product_placeholder.php?'.http_build_query(['name'=>$product['product_name'],'stock'=>$product['sku'],'cat'=>$product['category_name']])) ?>'"><div class="pp-meta"><span>Stock <?= product_h($product['sku']) ?></span><span><?= product_h($product['verification_status']?:'placeholder') ?></span></div><?php if($product['source_page_url']):?><div class="pp-source"><b>Online image source</b><span><?= product_h($product['source_name']) ?></span><small>Image remains marked for review until pack/flavour match is confirmed.</small></div><?php endif;?></article><article class="os-card pp-detail-main"><span class="pp-stock">Stock <?= product_h($product['sku']) ?></span><h1><?= product_h($product['product_name']) ?></h1><p><?= product_h($product['category_name']) ?> • <?= product_h($product['market_name']) ?> • <?= product_h($product['currency_code']) ?></p><div class="pp-meta"><span>Product ID #<?= (int)$product['id'] ?></span><span><?= product_h($product['status']) ?></span><?php if($product['pack_size']):?><span><?= product_h(rtrim(rtrim(number_format((float)$product['pack_size'],3,'.',''),'0'),'.').' '.$product['pack_unit']) ?></span><?php endif;?></div><?php if($history):?><div class="pp-price-row"><div class="pp-price"><small>MRP</small><b>₹<?= number_format((float)$history[0]['mrp'],2) ?></b></div><div class="pp-price"><small>Volume Points</small><b class="pp-vp"><?= product_h(rtrim(rtrim(number_format((float)$history[0]['volume_points'],3,'.',''),'0'),'.')) ?> VP</b></div></div><div class="pp-tier-grid"><?php foreach($tiers as $t):?><div class="pp-tier"><small><?= product_h($t['tier_name']) ?></small><b>₹<?= number_format((float)$t['price_amount'],2) ?></b></div><?php endforeach;?></div><?php endif;?></article></section><section class="os-card" style="margin-top:14px"><div class="os-title-row"><div><h2>Price History</h2><p>Old values are not overwritten when a future price list uses a new effective date.</p></div><a class="os-btn" href="product_price_history.php?q=<?= rawurlencode((string)$product['sku']) ?>">Open Full History</a></div><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Effective From</th><th>Effective To</th><th>MRP</th><th>VP</th><th>Status</th></tr></thead><tbody><?php foreach($history as $h):?><tr><td><?= product_h($h['effective_from']) ?></td><td><?= product_h($h['effective_to']?:'Current') ?></td><td>₹<?= number_format((float)$h['mrp'],2) ?></td><td><?= product_h(rtrim(rtrim(number_format((float)$h['volume_points'],3,'.',''),'0'),'.')) ?></td><td><span class="pp-badge"><?= product_h($h['status']) ?></span></td></tr><?php endforeach;?></tbody></table></div></section><?php endif;?></main></div></body></html>